        "zh": "“过来，莫普。”吉尔说。可是莫普没有过来。",
        "alt": "“过来，莫普。”吉尔说。可是莫普没有过来。",
        "tip": "可以用玩偶或手指演动作，只在平整地面活动；不模仿高处或浴缸里的跳跃。",
