    "guide": {
      "synopsis": "帕姆和蒂姆用积木搭房子、墙、路、隧道、桥和楼房。两人想合作搭更大的建筑，结尾却出现意外。",
      "patterns": [
        {
          "pattern": "I made … with the blocks.",
          "meaning": "我用积木搭了……",
          "question": "What did you make?",
          "questionZh": "你搭了什么？",
          "answer": "I made a bridge with the blocks.",
          "answerZh": "我用积木搭了一座桥。",
          "note": "亲子问答为叽咕补充，示范回答可换成孩子自己的发现。"
        }
      ],
      "goals": [
        "结合画面认识积木、桥、楼房中的一到三个词，能指认即可。",
        "听懂或尝试使用“I made … with the blocks.”（我用积木搭了……），不要求背诵。"
      ],
      "task": {
        "title": "读完一起做一件小事",
        "text": "搭一座低矮的桥或小房子，邀请孩子用一个词介绍作品；倒了也可以再试。",
        "hint": "指一指、动一动、说一个词都算参与；孩子不想做时就先放下。"
      }
    },
